"use client"

import * as React from "react"

import { AppShell } from "@/components/shell/app-shell"
import {
  ModelCatalogPage,
  type CatalogState,
} from "@/components/mockups/model-catalog/catalog-page"
import { MockupShell } from "@/components/shell/mockup-shell"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"

export default function ModelCatalogRoute() {
  const [state, setState] = React.useState<CatalogState>("populated")

  return (
    <MockupShell
      title="Model catalog — onboarding LLM, activating TTS"
      actions={
        <ToggleGroup
          onValueChange={(next) => {
            if (next) setState(next as CatalogState)
          }}
          size="sm"
          type="single"
          value={state}
          variant="outline"
        >
          <ToggleGroupItem value="populated">Populated</ToggleGroupItem>
          <ToggleGroupItem value="empty">Empty</ToggleGroupItem>
          <ToggleGroupItem value="loading">Loading</ToggleGroupItem>
          <ToggleGroupItem value="error">Error</ToggleGroupItem>
        </ToggleGroup>
      }
    >
      <AppShell active="Models">
        <div className="flex flex-1 flex-col p-3 lg:p-4">
          <ModelCatalogPage state={state} />
        </div>
      </AppShell>
    </MockupShell>
  )
}

"use client"

import * as React from "react"

import { toast } from "sonner"

import {
  BackToPickerIcon,
  FetchWarningIcon,
  FieldHelpIcon,
  NewProviderIcon,
  RetryIcon,
  TestFailedIcon,
  TestPassedIcon,
} from "@/components/mockups/model-catalog/icons"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Field,
  FieldDescription,
  FieldLabel,
  FieldSeparator,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Spinner } from "@/components/ui/spinner"
import { Textarea } from "@/components/ui/textarea"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  liveModelsFor,
  MODALITIES,
  PROVIDERS,
  providerById,
  type Modality,
} from "@/lib/mockups/model-catalog-data"
import { cn } from "@/lib/utils"

const NEW_PROVIDER = "__new__"

const EXAMPLES: Record<Modality, { model: string; name: string }> = {
  llm: { model: "llama-3.3-70b-versatile", name: "Llama 3.3 70B" },
  tts: { model: "eleven_flash_v2_5", name: "ElevenLabs Flash v2.5" },
}

type Mode = "pick" | "connect"
type FetchState = "idle" | "loading" | "ready" | "failed"
type TestState = "idle" | "running" | "passed" | "failed"

export function AddModelDialog({
  modality,
  onOpenChange,
  open,
}: {
  modality: Modality
  onOpenChange: (open: boolean) => void
  open: boolean
}) {
  return (
    <Dialog onOpenChange={onOpenChange} open={open}>
      {/* The body is the only row that scrolls, so the header, the footer and
          the Save gate stay put however long the heavy path gets. */}
      <DialogContent className="grid-rows-[auto_1fr_auto] max-h-[85vh] sm:max-w-lg">
        <AddModelBody
          key={modality}
          modality={modality}
          onDone={() => onOpenChange(false)}
        />
      </DialogContent>
    </Dialog>
  )
}

function AddModelBody({
  modality,
  onDone,
}: {
  modality: Modality
  onDone: () => void
}) {
  const [mode, setMode] = React.useState<Mode>("pick")
  const [providerId, setProviderId] = React.useState("")
  const [modelId, setModelId] = React.useState("")
  const [displayName, setDisplayName] = React.useState("")
  const [notes, setNotes] = React.useState("")
  const [manual, setManual] = React.useState(false)
  const [fetchState, setFetchState] = React.useState<FetchState>("idle")
  const [testState, setTestState] = React.useState<TestState>("idle")

  const [newProviderName, setNewProviderName] = React.useState("")
  const [baseUrl, setBaseUrl] = React.useState("")
  const [apiKey, setApiKey] = React.useState("")

  const modalityLabel =
    MODALITIES.find((option) => option.id === modality)?.label ?? ""
  const provider = providerById(providerId)
  const connecting = mode === "connect"
  const eligible = PROVIDERS.filter((option) =>
    option.modalities.includes(modality),
  )

  const usesLiveList =
    !connecting &&
    provider?.listsModels === true &&
    !manual &&
    fetchState !== "failed"

  const testRequired = !usesLiveList && (connecting || Boolean(provider))
  const testReady = connecting
    ? Boolean(
        newProviderName.trim() && baseUrl.trim() && apiKey && modelId.trim(),
      )
    : Boolean(modelId.trim())

  const canSave =
    Boolean(modelId.trim()) &&
    Boolean(displayName.trim()) &&
    (connecting
      ? Boolean(newProviderName.trim() && baseUrl.trim() && apiKey)
      : Boolean(provider)) &&
    (!testRequired || testState === "passed")

  function selectProvider(next: string) {
    setModelId("")
    setManual(false)
    setTestState("idle")

    if (next === NEW_PROVIDER) {
      setMode("connect")
      setProviderId("")
      setFetchState("idle")
      return
    }

    setProviderId(next)

    const chosen = providerById(next)
    if (chosen?.listsModels) {
      setFetchState("loading")
      /* Groq is stubbed to fail so the fallback is reachable. */
      window.setTimeout(() => {
        setFetchState(chosen.id === "groq" ? "failed" : "ready")
      }, 900)
    } else {
      setFetchState("idle")
    }
  }

  function backToPicker() {
    setMode("pick")
    setProviderId("")
    setModelId("")
    setNewProviderName("")
    setBaseUrl("")
    setApiKey("")
    setTestState("idle")
    setFetchState("idle")
  }

  function runTest() {
    setTestState("running")
    /* A stub short ID fails, so both outcomes are reachable. */
    window.setTimeout(() => {
      setTestState(modelId.trim().length > 3 ? "passed" : "failed")
    }, 1100)
  }

  function save() {
    toast.success(`${displayName.trim()} added to the ${modalityLabel} catalog`)
    onDone()
  }

  return (
    <>
      <DialogHeader>
        {connecting ? (
          <Button
            className="-ms-2 self-start"
            onClick={backToPicker}
            size="xs"
            variant="ghost"
          >
            <BackToPickerIcon className="rtl:rotate-180" />
            Connected providers
          </Button>
        ) : null}

        <DialogTitle>
          {connecting ? "Connect a provider" : `Add ${modalityLabel} model`}
        </DialogTitle>
        <DialogDescription>
          {connecting
            ? "Adds the connection and its first model together."
            : `Adds it to the ${modalityLabel} picker in Global and Org Settings.`}
        </DialogDescription>
      </DialogHeader>

      {/* The ±1 pair gives focus rings room to draw inside the scroll box. */}
      <div className="-mx-1 flex min-h-0 flex-col gap-4 overflow-y-auto px-1 pb-1">
        {connecting ? (
          <>
            <Field>
              <FieldLabel htmlFor="provider-name">Provider name</FieldLabel>
              <Input
                id="provider-name"
                onChange={(event) => setNewProviderName(event.target.value)}
                placeholder="Fireworks"
                value={newProviderName}
              />
            </Field>

            <Field>
              <HelpLabel
                help="Must accept OpenAI-spec requests."
                htmlFor="base-url"
              >
                Base URL
              </HelpLabel>
              <Input
                id="base-url"
                onChange={(event) => {
                  setBaseUrl(event.target.value)
                  setTestState("idle")
                }}
                placeholder="https://api.fireworks.ai/inference/v1"
                value={baseUrl}
              />
            </Field>

            <Field>
              <FieldLabel htmlFor="api-key">API key</FieldLabel>
              <Input
                id="api-key"
                onChange={(event) => {
                  setApiKey(event.target.value)
                  setTestState("idle")
                }}
                placeholder="sk-…"
                type="password"
                value={apiKey}
              />
              {/* The one inline sentence in this dialog. A credential you
                  cannot read back is irreversible, which is the case the
                  helper-text rule keeps inline copy for. */}
              <FieldDescription>
                Stored once and never shown again.
              </FieldDescription>
            </Field>

            {/* A labelled rule rather than a heading: the form is doing two
                things, and a section title at the dialog title's own size
                would compete with it for the same job. */}
            <FieldSeparator>Model</FieldSeparator>

            <Field>
              <HelpLabel
                help="Sent to the provider exactly as typed."
                htmlFor="model"
              >
                Model identifier
              </HelpLabel>
              <Input
                id="model"
                onChange={(event) => {
                  setModelId(event.target.value)
                  setTestState("idle")
                }}
                placeholder={EXAMPLES[modality].model}
                value={modelId}
              />
            </Field>
          </>
        ) : (
          <>
            <Field>
              <FieldLabel htmlFor="provider">Provider</FieldLabel>
              <Select onValueChange={selectProvider} value={providerId}>
                <SelectTrigger className="w-full" id="provider">
                  <SelectValue placeholder="Pick a provider" />
                </SelectTrigger>
                <SelectContent position="popper">
                  {eligible.map((option) => (
                    <SelectItem key={option.id} value={option.id}>
                      {option.name}
                    </SelectItem>
                  ))}
                  <SelectSeparator />
                  {/* The heavier action, kept visibly apart from the
                      connections that already exist rather than sitting in
                      the same list as one more provider. */}
                  <SelectItem value={NEW_PROVIDER}>
                    <NewProviderIcon />
                    Connect a new provider…
                  </SelectItem>
                </SelectContent>
              </Select>
            </Field>

            {provider ? (
              <ModelField
                fetchState={fetchState}
                modelPlaceholder={EXAMPLES[modality].model}
                liveModels={liveModelsFor(provider.id, modality)}
                manual={manual}
                modelId={modelId}
                onManualChange={(next) => {
                  setManual(next)
                  setModelId("")
                  setTestState("idle")
                }}
                onModelIdChange={(next) => {
                  setModelId(next)
                  setTestState("idle")
                }}
                onRetryFetch={() => selectProvider(provider.id)}
                providerListsModels={provider.listsModels}
                providerName={provider.name}
                usesLiveList={usesLiveList}
              />
            ) : null}
          </>
        )}

        {testRequired ? (
          <ConnectionTest onRun={runTest} ready={testReady} state={testState} />
        ) : null}

        {connecting || provider ? (
          <>
            <FieldSeparator />

            <Field>
              <HelpLabel
                help="The name this model is picked by in settings."
                htmlFor="display-name"
              >
                Display name
              </HelpLabel>
              <Input
                id="display-name"
                onChange={(event) => setDisplayName(event.target.value)}
                placeholder={EXAMPLES[modality].name}
                value={displayName}
              />
            </Field>

            <Field>
              <FieldLabel htmlFor="notes">Notes (optional)</FieldLabel>
              <Textarea
                id="notes"
                onChange={(event) => setNotes(event.target.value)}
                placeholder="English only — Arabic calls must not be routed here."
                rows={2}
                value={notes}
              />
            </Field>
          </>
        ) : null}
      </div>

      <DialogFooter>
        <Button onClick={onDone} variant="ghost">
          Cancel
        </Button>
        <Button disabled={!canSave} onClick={save}>
          Add model
        </Button>
      </DialogFooter>
    </>
  )
}

function HelpLabel({
  children,
  help,
  htmlFor,
}: {
  children: string
  help: string
  htmlFor: string
}) {
  return (
    <div className="flex items-center gap-1.5">
      <FieldLabel htmlFor={htmlFor}>{children}</FieldLabel>
      <Tooltip>
        <TooltipTrigger
          aria-label={`About ${children}`}
          className="text-muted-foreground hover:text-foreground"
        >
          <FieldHelpIcon className="size-3.5" />
        </TooltipTrigger>
        <TooltipContent className="max-w-64">{help}</TooltipContent>
      </Tooltip>
    </div>
  )
}

function ModelField({
  fetchState,
  liveModels,
  manual,
  modelId,
  modelPlaceholder,
  onManualChange,
  onModelIdChange,
  onRetryFetch,
  providerListsModels,
  providerName,
  usesLiveList,
}: {
  fetchState: FetchState
  liveModels: string[]
  manual: boolean
  modelId: string
  modelPlaceholder: string
  onManualChange: (manual: boolean) => void
  onModelIdChange: (modelId: string) => void
  onRetryFetch: () => void
  providerListsModels: boolean
  providerName: string
  usesLiveList: boolean
}) {
  if (fetchState === "loading") {
    return (
      <Field>
        <FieldLabel>Model</FieldLabel>
        <div className="flex h-8 items-center gap-2 rounded-lg bg-muted px-3 text-sm text-muted-foreground">
          <Spinner />
          Fetching {providerName}&apos;s models…
        </div>
      </Field>
    )
  }

  return (
    <Field>
      {fetchState === "failed" ? (
        <Alert>
          <FetchWarningIcon />
          <AlertTitle>
            Couldn&apos;t reach {providerName}&apos;s model list
          </AlertTitle>
          <AlertDescription>
            Enter the model ID and test it instead.
          </AlertDescription>
        </Alert>
      ) : null}

      <div className="flex items-center gap-2">
        {usesLiveList ? (
          <>
            <FieldLabel htmlFor="model">Model</FieldLabel>
            {/* Provenance in three words rather than the two-line paragraph
                this used to carry. */}
            <Badge variant="outline">Live from {providerName}</Badge>
          </>
        ) : (
          <HelpLabel
            help="Sent to the provider exactly as typed."
            htmlFor="model"
          >
            Model identifier
          </HelpLabel>
        )}
      </div>

      {usesLiveList ? (
        <Select onValueChange={onModelIdChange} value={modelId}>
          <SelectTrigger className="w-full" id="model">
            <SelectValue placeholder="Pick a model" />
          </SelectTrigger>
          <SelectContent position="popper">
            {liveModels.map((option) => (
              <SelectItem key={option} value={option}>
                {option}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      ) : (
        <Input
          id="model"
          onChange={(event) => onModelIdChange(event.target.value)}
          placeholder={modelPlaceholder}
          value={modelId}
        />
      )}

      {/* An escape, not an explainer: every one of these is an action the admin
          can take when the field in front of them is the wrong one. */}
      {/* `Field` puts `*:w-full` on its direct children, so a button that
          should hug its own text stretches and centres. The wrapper takes the
          full width and lets the button keep its intrinsic one. */}
      <div className="flex">
        {usesLiveList ? (
          <Button onClick={() => onManualChange(true)} size="xs" variant="link">
            Not seeing it? Enter the ID manually
          </Button>
        ) : fetchState === "failed" ? (
          <Button onClick={onRetryFetch} size="xs" variant="outline">
            <RetryIcon />
            Try the list again
          </Button>
        ) : manual && providerListsModels ? (
          <Button
            onClick={() => onManualChange(false)}
            size="xs"
            variant="link"
          >
            Back to {providerName}&apos;s list
          </Button>
        ) : null}
      </div>
    </Field>
  )
}

function ConnectionTest({
  onRun,
  ready,
  state,
}: {
  onRun: () => void
  ready: boolean
  state: TestState
}) {
  const passed = state === "passed"
  const failed = state === "failed"

  return (
    <div className="flex flex-col gap-3 rounded-lg bg-muted p-3">
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium">Connection test</span>
          {/* One word in place of the sentence that used to say Save is
              blocked — the disabled Save button already says that. */}
          <Badge variant="outline">Required</Badge>
        </div>
        <Button
          disabled={!ready || state === "running"}
          onClick={onRun}
          size="sm"
          variant="outline"
        >
          {state === "running" ? <Spinner /> : null}
          {state === "running" ? "Testing…" : passed ? "Test again" : "Test"}
        </Button>
      </div>

      {passed || failed ? (
        <div className="flex items-start gap-2 rounded-lg bg-card p-3 text-sm">
          {passed ? (
            <TestPassedIcon className="mt-0.5 size-4 shrink-0 text-success" />
          ) : (
            <TestFailedIcon className="mt-0.5 size-4 shrink-0 text-destructive" />
          )}
          <span className={cn(!passed && "text-foreground")}>
            {passed
              ? "The provider answered in 412 ms."
              : "The provider rejected that model ID — check it against their own documentation."}
          </span>
        </div>
      ) : null}
    </div>
  )
}

"use client"

import * as React from "react"

import { toast } from "sonner"

import { AddModelDialog } from "@/components/mockups/model-catalog/add-model-dialog"
import {
  AddModelIcon,
  LoadFailedIcon,
  ModelIcon,
  NoteIcon,
  RetryIcon,
  SearchIcon,
} from "@/components/mockups/model-catalog/icons"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Skeleton } from "@/components/ui/skeleton"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  CATALOG,
  MODALITIES,
  canOnboard,
  providerById,
  type CatalogEntry,
  type Modality,
} from "@/lib/mockups/model-catalog-data"
import { cn } from "@/lib/utils"

export type CatalogState = "populated" | "empty" | "loading" | "error"

export function ModelCatalogPage({ state }: { state: CatalogState }) {
  const [entries, setEntries] = React.useState<CatalogEntry[]>(CATALOG)
  const [modality, setModality] = React.useState<Modality>("llm")
  const [search, setSearch] = React.useState("")
  const [statusFilter, setStatusFilter] = React.useState("all")
  const [addOpen, setAddOpen] = React.useState(false)

  function toggleActive(entry: CatalogEntry) {
    const nowActive = !entry.active

    setEntries((previous) =>
      previous.map((item) =>
        item.id === entry.id ? { ...item, active: nowActive } : item,
      ),
    )

    toast(
      nowActive
        ? `${entry.displayName} is selectable again`
        : `${entry.displayName} removed from future selection`,
      {
        description: nowActive
          ? undefined
          : "Organizations already using it keep working.",
        action: {
          label: "Undo",
          onClick: () =>
            setEntries((previous) =>
              previous.map((item) =>
                item.id === entry.id ? { ...item, active: entry.active } : item,
              ),
            ),
        },
      },
    )
  }

  const filtersOn = search.trim() !== "" || statusFilter !== "all"

  return (
    <div className="flex flex-col gap-4">
      {/* The page had no title — breadcrumb ran straight into this line, so the
          description was doing an h1's job at a description's weight. One h1
          per page, and every sibling index page has one. */}
      <header className="flex flex-col gap-1">
        <h1 className="text-2xl font-semibold">Models</h1>
        <p className="max-w-2xl text-sm text-muted-foreground">
          Models Sarj staff have onboarded. Anything active here is selectable
          in every organization&apos;s settings.
        </p>
      </header>

      <Tabs
        className="gap-4"
        onValueChange={(value) => setModality(value as Modality)}
        value={modality}
      >
        <TabsList className="w-fit">
          {MODALITIES.map((option) => (
            <TabsTrigger key={option.id} value={option.id}>
              {option.label}
            </TabsTrigger>
          ))}
        </TabsList>

        {MODALITIES.map((option) => {
          const all =
            state === "empty"
              ? []
              : entries.filter((entry) => entry.modality === option.id)

          const rows = all.filter((entry) => {
            if (statusFilter === "active" && !entry.active) return false
            if (statusFilter === "inactive" && entry.active) return false
            if (!search.trim()) return true
            const provider = providerById(entry.providerId)
            return `${entry.displayName} ${entry.modelId} ${provider?.name ?? ""}`
              .toLowerCase()
              .includes(search.trim().toLowerCase())
          })

          return (
            <TabsContent
              className="flex flex-col gap-3"
              key={option.id}
              value={option.id}
            >
              {/* Search and the action that adds to the table share one row,
                  its right edge against the table's — the same call as the
                  Knowledge Bases index.

                  They come and go separately, though. A search box over a list
                  that is loading, failed or empty is a control with no subject;
                  Add still has one, so only the filters go. */}
              {state === "populated" || canOnboard(option.id) ? (
                <div className="flex flex-wrap items-center gap-3">
                  {state === "populated" ? (
                    <>
                      <InputGroup className="max-w-64 bg-card">
                        <InputGroupAddon>
                          <SearchIcon />
                        </InputGroupAddon>
                        <InputGroupInput
                          aria-label="Search models"
                          onChange={(event) => setSearch(event.target.value)}
                          placeholder="Search models…"
                          value={search}
                        />
                      </InputGroup>

                      <Select
                        onValueChange={setStatusFilter}
                        value={statusFilter}
                      >
                        <SelectTrigger
                          aria-label="Filter by status"
                          className="bg-card"
                        >
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent position="popper">
                          <SelectItem value="all">All statuses</SelectItem>
                          <SelectItem value="active">Active</SelectItem>
                          <SelectItem value="inactive">Deactivated</SelectItem>
                        </SelectContent>
                      </Select>
                    </>
                  ) : null}

                  {/* `ms-auto` rather than justify-between: on a loading or
                      failed tab this button is the row's only child, and
                      justify-between would park it on the left. */}
                  {canOnboard(option.id) ? (
                    <Button
                      className="ms-auto"
                      onClick={() => setAddOpen(true)}
                    >
                      <AddModelIcon />
                      Add model
                    </Button>
                  ) : null}
                </div>
              ) : null}

              <CatalogBody
                canAdd={canOnboard(option.id)}
                filtersOn={filtersOn}
                label={option.label}
                onAdd={() => setAddOpen(true)}
                onClearFilters={() => {
                  setSearch("")
                  setStatusFilter("all")
                }}
                onToggle={toggleActive}
                rows={rows}
                state={state}
              />
            </TabsContent>
          )
        })}
      </Tabs>

      <AddModelDialog
        modality={modality}
        onOpenChange={setAddOpen}
        open={addOpen}
      />
    </div>
  )
}

function CatalogBody({
  canAdd,
  filtersOn,
  label,
  onAdd,
  onClearFilters,
  onToggle,
  rows,
  state,
}: {
  canAdd: boolean
  filtersOn: boolean
  label: string
  onAdd: () => void
  onClearFilters: () => void
  onToggle: (entry: CatalogEntry) => void
  rows: CatalogEntry[]
  state: CatalogState
}) {
  if (state === "loading") {
    return (
      <Card className="[--card-spacing:0px]">
        <div className="overflow-x-auto">
          <Table>
            <CatalogHead />
            <TableBody>
              {Array.from({ length: 5 }, (_, index) => (
                <TableRow key={index}>
                  <TableCell>
                    <Skeleton className="h-4 w-20" />
                  </TableCell>
                  <TableCell>
                    <Skeleton className="h-4 w-32" />
                  </TableCell>
                  <TableCell>
                    <Skeleton className="h-4 w-28" />
                  </TableCell>
                  <TableCell>
                    <Skeleton className="h-5 w-14 rounded-4xl" />
                  </TableCell>
                  <TableCell>
                    <Skeleton className="ms-auto h-6 w-20" />
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      </Card>
    )
  }

  if (state === "error") {
    return (
      <Empty>
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <LoadFailedIcon />
          </EmptyMedia>
          <EmptyTitle>Couldn&apos;t load the catalog</EmptyTitle>
          <EmptyDescription>
            Nothing has changed — the list just didn&apos;t come back.
          </EmptyDescription>
        </EmptyHeader>
        <EmptyContent>
          <Button variant="outline">
            <RetryIcon />
            Try again
          </Button>
        </EmptyContent>
      </Empty>
    )
  }

  if (rows.length === 0 && filtersOn) {
    return (
      <Empty>
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <SearchIcon />
          </EmptyMedia>
          <EmptyTitle>No models match</EmptyTitle>
          <EmptyDescription>
            Nothing in the {label} catalog matches the filters you set.
          </EmptyDescription>
        </EmptyHeader>
        <EmptyContent>
          <Button onClick={onClearFilters} variant="outline">
            Clear filters
          </Button>
        </EmptyContent>
      </Empty>
    )
  }

  if (rows.length === 0) {
    return (
      <Empty>
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <ModelIcon />
          </EmptyMedia>
          <EmptyTitle>No {label} models yet</EmptyTitle>
          {/* The only place the missing Add button needs explaining. On a
              populated TTS tab the rows and their actions say what the screen
              does; on an empty one there would otherwise be nothing at all. */}
          <EmptyDescription>
            {canAdd
              ? "Add one and it becomes selectable for every organization on the platform."
              : "TTS models ship with the platform, so there is nothing to add here."}
          </EmptyDescription>
        </EmptyHeader>
        {canAdd ? (
          <EmptyContent>
            <Button onClick={onAdd}>
              <AddModelIcon />
              Add model
            </Button>
          </EmptyContent>
        ) : null}
      </Empty>
    )
  }

  return (
    <Card className="[--card-spacing:0px]">
      <div className="overflow-x-auto">
        <Table>
          <CatalogHead />
          <TableBody>
            {rows.map((entry) => (
              <CatalogRow entry={entry} key={entry.id} onToggle={onToggle} />
            ))}
          </TableBody>
        </Table>
      </div>
    </Card>
  )
}

function CatalogHead() {
  return (
    <TableHeader>
      <TableRow>
        <TableHead>Provider</TableHead>
        <TableHead>Model</TableHead>
        <TableHead>Display name</TableHead>
